from pathlib import Path
import subprocess,json,importlib.util,hashlib,time
r=Path.cwd();binary=r/'build-ru1/ceRU1LifetimeBench';out=Path('/tmp/ce-ru1-i06')
s=importlib.util.spec_from_file_location('checks',r/'tests/relation_update_spine_v1/evidence_contract_test.py');checks=importlib.util.module_from_spec(s);s.loader.exec_module(checks)
cases=[]
def add(group,fixture,profile,route,modules,horizon,reuse='refresh',width=16,repeats=7):
 cases.append({'group':group,'fixture':fixture,'profile':profile,'route':route,'modules':modules,'horizon':horizon,'reuse':reuse,'width':width,'repeats':repeats})
for fixture in ['dense','mixed','irregular']:
 for profile,route in [('full_f32','sparse'),('half','sparse')]+([('half','hybrid')] if fixture!='irregular' else []):
  for horizon in [1,16,128,1024]:add('main',fixture,profile,route,256,horizon)
for fixture in ['dense','mixed']:
 for route in ['sparse','hybrid']:
  for horizon in [1,128]:add('tiny',fixture,'half',route,1,horizon)
  add('fixed_version',fixture,'half',route,256,128,'fixed')
for repeat in range(3):
 for route in ['sparse','hybrid']:add('cold_repeat_'+str(repeat),'mixed','half',route,256,128,repeats=1)
add('n1_forward_only','dense','full_f32','sparse',256,128,width=1)
results=[]
for i,c in enumerate(cases):
 cmd=[str(binary),'--fixture',c['fixture'],'--profile',c['profile'],'--route',c['route'],'--modules',str(c['modules']),'--horizon',str(c['horizon']),'--operand-reuse',c['reuse'],'--width',str(c['width']),'--repeats',str(c['repeats']),'--warmup','2']
 print('MEASURE',i+1,'/',len(cases),c,flush=True)
 begin=time.time();p=subprocess.run(cmd,text=True,capture_output=True)
 rows=[json.loads(line) for line in p.stdout.splitlines() if line.startswith('{')]
 record={'run_id':i,'case':c,'argv':cmd,'exit_code':p.returncode,'stdout':p.stdout,'stderr':p.stderr,'raw_log_sha256':hashlib.sha256(p.stdout.encode()).hexdigest(),'samples':rows,'elapsed_seconds':time.time()-begin}
 results.append(record);(out/'measurements.json').write_text(json.dumps(results,indent=2)+'\n')
 if p.returncode:raise RuntimeError(p.stderr)
 checks.validate_samples(rows)
 print('PASS samples',len(rows),'median input complete',flush=True)
negative=[]
for fixture,profile,reason in [('irregular','half','no legal nonempty bounded rectangular cover'),('dense','full_f32','full-f32 semantics cannot use WMMA')]:
 cmd=[str(binary),'--fixture',fixture,'--profile',profile,'--route','hybrid','--modules','256','--horizon','1','--repeats','1','--warmup','0']
 p=subprocess.run(cmd,text=True,capture_output=True)
 assert p.returncode!=0 and reason in p.stderr,(p.returncode,p.stdout,p.stderr)
 negative.append({'argv':cmd,'exit_code':p.returncode,'stdout':p.stdout,'stderr':p.stderr,'expected_reason':reason})
(out/'negative_controls.json').write_text(json.dumps(negative,indent=2)+'\n')
print('PERFORMANCE_MATRIX_PASS',len(results),'processes',sum(len(x['samples']) for x in results),'samples',len(negative),'negative controls',flush=True)
